import React, { useState, useEffect } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    categories: [],
    priorities: [],
    limits: {},
    questionnaire: {}
  });

  // ✅ CHECK EXISTING USER
  useEffect(() => {
    const saved = localStorage.getItem("userData");

    if (saved) {
      setData(JSON.parse(saved));
      setStep("dashboard"); // 🔥 skip flow
    }
  }, []);

  // ✅ SAVE USER DATA
  const updateData = (newData) => {
    const updated = { ...data, ...newData };
    setData(updated);
    localStorage.setItem("userData", JSON.stringify(updated));
  };

  return (
    <>
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            updateData({ income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          onNext={(answers) => {
            updateData({ questionnaire: answers });
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          onNext={(priorities) => {
            updateData({ priorities });
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.categories}
          onNext={(limits) => {
            updateData({ limits });

            // ✅ FINAL SAVE
            localStorage.setItem("userData", JSON.stringify({
              ...data,
              limits
            }));

            setStep("dashboard");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "dashboard" && (
        <Dashboard userData={data} updateData={updateData} />
      )}
    </>
  );
}

export default App;
